$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
  throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backup = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/academic_calendar_phase2_wizard_$stamp"

function ReadProject([string]$p) {
  $f = Join-Path $root $p
  if (-not (Test-Path $f)) { throw "Missing: $p" }
  return [IO.File]::ReadAllText($f).Replace("`r`n", "`n")
}

function WriteProject([string]$p, [string]$c) {
  $f = Join-Path $root $p
  New-Item -ItemType Directory -Path (Split-Path $f -Parent) -Force | Out-Null
  [IO.File]::WriteAllText($f, $c, $utf8)
  Write-Host "Created/updated: $p" -ForegroundColor Green
}

function BackupProject([string]$p) {
  $s = Join-Path $root $p
  if (Test-Path $s) {
    $d = Join-Path $backup $p
    New-Item -ItemType Directory -Path (Split-Path $d -Parent) -Force | Out-Null
    Copy-Item $s $d -Force
  }
}

function EnsureBefore(
  [string]$content,
  [string]$marker,
  [string]$anchor,
  [string]$block
) {
  if ($content.Contains($marker)) { return $content }
  $i = $content.IndexOf($anchor)
  if ($i -lt 0) { throw "Anchor not found: $anchor" }
  return $content.Substring(0, $i) + $block + $content.Substring($i)
}

$payloads = @{
  'lib/features/academic_calendar/domain/entities/academic_year_config_entity.dart' = ''
  'lib/features/academic_calendar/data/models/academic_year_config_model.dart' = ''
  'lib/features/academic_calendar/domain/repositories/academic_year_config_repository.dart' = ''
  'lib/features/academic_calendar/data/repositories/academic_year_config_repository_impl.dart' = ''
  'lib/features/academic_calendar/domain/usecases/save_academic_year_wizard.dart' = ''
  'lib/features/academic_calendar/presentation/bloc/academic_year_wizard_bloc.dart' = ''
  'lib/features/academic_calendar/presentation/pages/academic_year_wizard_page.dart' = ''
}
$paths = 'lib/core/constants/firestore_paths.dart'
$sl = 'lib/core/di/service_locator.dart'
$calendarPage = 'lib/features/academic_calendar/presentation/pages/academic_calendar_page.dart'

foreach ($p in @($paths, $sl, $calendarPage) + $payloads.Keys) {
  BackupProject $p
}

foreach ($item in $payloads.GetEnumerator()) {
  WriteProject $item.Key (
    [Text.Encoding]::UTF8.GetString(
      [Convert]::FromBase64String($item.Value)
    )
  )
}

$content = ReadProject $paths
if (-not $content.Contains('academicYearConfigs')) {
  $content = $content.Replace(
    "`n}",
    "`n  static const String academicYearConfigs = 'academic_year_configs';`n}"
  )
}
WriteProject $paths $content

$content = ReadProject $sl

$content = EnsureBefore `
  $content `
  'academic_year_config_repository_impl.dart' `
  "import '../../features/academic_calendar/data/repositories/academic_calendar_repository_impl.dart';" `
  "import '../../features/academic_calendar/data/repositories/academic_year_config_repository_impl.dart';`n"

$content = EnsureBefore `
  $content `
  'academic_year_config_repository.dart' `
  "import '../../features/academic_calendar/domain/repositories/academic_calendar_repository.dart';" `
  "import '../../features/academic_calendar/domain/repositories/academic_year_config_repository.dart';`nimport '../../features/academic_calendar/domain/usecases/save_academic_year_wizard.dart';`n"

$content = EnsureBefore `
  $content `
  'academic_year_wizard_bloc.dart' `
  "import '../../features/academic_calendar/presentation/bloc/academic_calendar_bloc.dart';" `
  "import '../../features/academic_calendar/presentation/bloc/academic_year_wizard_bloc.dart';`n"

$repoReg = @'
  sl.registerLazySingleton<AcademicYearConfigRepository>(
    () => AcademicYearConfigRepositoryImpl(
      sl<FirebaseFirestoreService>(),
    ),
  );

  sl.registerLazySingleton<SaveAcademicYearWizard>(
    () => SaveAcademicYearWizard(
      sl<AcademicYearConfigRepository>(),
      sl<AcademicCalendarRepository>(),
    ),
  );

'@

$content = EnsureBefore `
  $content `
  'registerLazySingleton<AcademicYearConfigRepository>' `
  '  sl.registerLazySingleton<AcademicCalendarRepository>(' `
  $repoReg

$blocReg = @'
  sl.registerFactory<AcademicYearWizardBloc>(
    () => AcademicYearWizardBloc(
      sl<AcademicYearConfigRepository>(),
      sl<SaveAcademicYearWizard>(),
    ),
  );

'@

$content = EnsureBefore `
  $content `
  'registerFactory<AcademicYearWizardBloc>' `
  '  sl.registerFactory<AcademicCalendarBloc>(' `
  $blocReg

WriteProject $sl $content

$content = ReadProject $calendarPage

if (-not $content.Contains("import 'academic_year_wizard_page.dart';")) {
  $content = $content.Replace(
    "import '../bloc/academic_calendar_bloc.dart';",
    "import '../bloc/academic_calendar_bloc.dart';`nimport 'academic_year_wizard_page.dart';"
  )
}

if (-not $content.Contains('const AcademicYearWizardPage()')) {
  $oldAppBar = "      appBar: AppBar(title: const Text('Academic Calendar')),"
  $newAppBar = @'
      appBar: AppBar(
        title: const Text('Academic Calendar'),
        actions: [
          TextButton.icon(
            onPressed: () async {
              await Navigator.of(context).push<void>(
                MaterialPageRoute<void>(
                  builder: (_) => const AcademicYearWizardPage(),
                ),
              );
              if (context.mounted) {
                _loadMonth();
              }
            },
            icon: const Icon(Icons.auto_awesome),
            label: const Text('Year Wizard'),
          ),
        ],
      ),
'@
  if (-not $content.Contains($oldAppBar)) {
    throw 'Academic Calendar AppBar anchor not found.'
  }
  $content = $content.Replace($oldAppBar, $newAppBar)
}

WriteProject $calendarPage $content

$format = @($paths, $sl, $calendarPage) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan
& dart format $format
if ($LASTEXITCODE -ne 0) { throw 'dart format failed.' }

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan
& flutter analyze
if ($LASTEXITCODE -ne 0) {
  throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Academic Calendar Phase 2 Academic Year Wizard completed successfully.' -ForegroundColor Green
Write-Host "Backup: $backup" -ForegroundColor DarkGray
